	debug = tagValues[0].value
	updateTriggerTime = tagValues[1].value
	errorMsg = ''
	timeNow = system.date.now()

	try:
		if not system.tag.readBlocking(["[kanoaMES]licenseInfo/qdsActive"])[0].value:
			errorMsg = 'QDS is inactive'
			if debug: log.info(errorMsg)
	except java.lang.Exception, e:
		errorMsg = e.cause
	except:
		errorMsg = 'unknown error'

	if errorMsg:
		system.tag.writeBlocking(["[.]lastUpdated", "[.]update", "[.]error"], [timeNow, 0, errorMsg])
		return		

	try:
		chkEventFilterInfo = {}	
		chkEventFilterInfo['auto'] = False
		chkEventFilterInfo['chkShtStateNames'] = ['Due', 'Overdue', 'Coming Due']
		data = system.kanoa.quality.event.getChkShtEvents(chkEventFilterInfo)
		if data != 'Kanoa QDS License Expired':
			chkEventFilterInfo = {}	
			chkEventFilterInfo['startDate'] = system.date.addDays(system.date.now(), -1)
			chkEventFilterInfo['endDate'] = system.date.now()
			chkEventFilterInfo['chkShtStateNames'] = ['Approved', 'Submitted', 'Rejected', 'Missed', 'Canceled']
			chkEventFilterInfo['auto'] = False

			chkEvents = system.dataset.appendDataset(data, system.kanoa.quality.event.getChkShtEvents(chkEventFilterInfo))
			system.tag.writeBlocking(["[.]data"], [chkEvents], 5000)				
		else:
			errorMsg = 'Kanoa QDS License Expired'
	except java.lang.Exception, e:
		errorMsg = e.cause
	except:
		errorMsg = 'unknown error'

	import time
	time.sleep(0.5)	#in case tag is being triggered manually, the change will be visible to the person

	if errorMsg: log.warn("%s timer script failed with %s"%(tagPath, errorMsg))
	system.tag.writeBlocking(["[.]lastUpdated", "[.]update", "[.]error"], [updateTriggerTime, 0, errorMsg])
	if debug: log.info("%s update took %sms"%(tagPath, system.date.millisBetween(timeNow, system.date.now())))

return

